/**
 * HookDAGValidatorEngine tests — HOOK-MANIFEST-DAG-MS26 / P0-U02
 *
 * Covers cycle detection, deterministic topological order, cross-source edge inference,
 * conflict surfacing (mixed-block-mode, duplicate-wiring), and the round-trip with a
 * real manifest generated by HookManifestEngine.
 */

import { describe, it, expect } from "vitest";
import { HookDAGValidatorEngine, hookDAGValidatorEngine } from "../engines/HookDAGValidatorEngine.js";
import { HookManifestEngine } from "../engines/HookManifestEngine.js";
import { HookDAGValidationSchema, HOOK_DAG_SCHEMA_VERSION } from "../schemas/hookDAGSchema.js";
import {
  HOOK_MANIFEST_SCHEMA_VERSION,
  type HookManifest,
  type HookEntry,
  type HookWiring,
} from "../schemas/hookManifestSchema.js";

// ── Fixture helpers ─────────────────────────────────────────────────────────

const FIXTURE_TIMESTAMP = "2026-05-12T00:00:00.000Z";

/** Make a `HookManifest` from a flat list of wirings; auto-fills hooks + events + stats. */
function makeManifest(input: {
  wirings: Array<{ file: string; event: string; source: string; order: number; matcher?: string; hardBlock?: boolean; args?: string; timeoutMs?: number }>;
  orphanFiles?: string[];
  repoRoot?: string;
}): HookManifest {
  const wiringsByFile = new Map<string, HookWiring[]>();
  for (const w of input.wirings) {
    const lst = wiringsByFile.get(w.file) ?? [];
    lst.push({
      event: w.event,
      matcher: w.matcher ?? "",
      timeoutMs: w.timeoutMs,
      continueOnError: w.hardBlock === true ? false : undefined,
      args: w.args,
      source: w.source,
      order: w.order,
    });
    wiringsByFile.set(w.file, lst);
  }
  for (const f of input.orphanFiles ?? []) {
    if (!wiringsByFile.has(f)) wiringsByFile.set(f, []);
  }
  const hooks: HookEntry[] = [...wiringsByFile.entries()]
    .map(([file, ws]): HookEntry => {
      const events = [...new Set(ws.map((w) => w.event))].sort();
      const hardBlock = ws.some((w) => w.continueOnError === false);
      return {
        id: file.split("/").pop()!.replace(/\.[^.]+$/, ""),
        file,
        kind: file.includes(".claude") ? "claude-mjs" : "mcp-ts",
        sizeBytes: 100,
        lineCount: 10,
        description: "",
        exports: [],
        wired: ws.length > 0,
        hardBlock,
        events,
        wirings: ws.slice().sort(
          (a, b) =>
            a.source.localeCompare(b.source) || a.event.localeCompare(b.event) || a.order - b.order || a.matcher.localeCompare(b.matcher),
        ),
      };
    })
    .sort((a, b) => a.file.localeCompare(b.file));
  const events: Record<string, string[]> = {};
  for (const w of input.wirings) {
    if (!events[w.event]) events[w.event] = [];
    if (!events[w.event].includes(w.file)) events[w.event].push(w.file);
  }
  return {
    schemaVersion: HOOK_MANIFEST_SCHEMA_VERSION,
    generatedAt: FIXTURE_TIMESTAMP,
    repoRoot: input.repoRoot ?? "/repo",
    hookDirs: ["/repo/.claude/hooks"],
    settingsFiles: [...new Set(input.wirings.map((w) => w.source))].sort(),
    hooks,
    events,
    danglingRefs: [],
    stats: {
      totalHooks: hooks.length,
      byKind: { "claude-mjs": hooks.filter((h) => h.kind === "claude-mjs").length, "mcp-ts": hooks.filter((h) => h.kind === "mcp-ts").length },
      byEvent: Object.fromEntries(
        [...new Set(input.wirings.map((w) => w.event))].map((e) => [e, new Set(input.wirings.filter((w) => w.event === e).map((w) => w.file)).size]),
      ),
      wired: hooks.filter((h) => h.wired).length,
      orphaned: hooks.filter((h) => !h.wired).length,
      hardBlock: hooks.filter((h) => h.hardBlock).length,
      danglingRefs: 0,
      totalLines: hooks.reduce((s, h) => s + h.lineCount, 0),
      eventTypes: [...new Set(input.wirings.map((w) => w.event))].sort(),
    },
  };
}

// ── Tests ───────────────────────────────────────────────────────────────────

describe("HookDAGValidatorEngine", () => {
  const eng = new HookDAGValidatorEngine();

  describe("smoke + interface", () => {
    it("exports a singleton with the correct class identity", () => {
      expect(hookDAGValidatorEngine).toBeInstanceOf(HookDAGValidatorEngine);
      expect(hookDAGValidatorEngine.constructor.name).toBe("HookDAGValidatorEngine");
    });

    it("getCapabilities lists exactly the three documented capabilities", () => {
      const caps = eng.getCapabilities().map((c) => c.name).sort();
      expect(caps).toEqual(["loadValidation", "validate", "validateAndWrite"]);
    });

    it("validateInput returns the error message naming the missing field", () => {
      expect(eng.validateInput({})).toBe("either `manifest` or a non-empty `manifestPath` must be provided");
      expect(eng.validateInput(null)).toBe("options object is required (pass at least `manifest` or `manifestPath`)");
      expect(eng.validateInput({ events: [] })).toBe("either `manifest` or a non-empty `manifestPath` must be provided");
    });

    it("validateInput returns null when a manifest object is supplied", () => {
      expect(eng.validateInput({ manifest: makeManifest({ wirings: [] }) })).toBeNull();
    });

    it("validate output passes its own Zod schema and pins schemaVersion to 1", () => {
      const out = eng.validate({ manifest: makeManifest({ wirings: [{ file: ".claude/hooks/a.mjs", event: "PreToolUse", source: "/repo/.claude/settings.json", order: 0 }] }) });
      expect(() => HookDAGValidationSchema.parse(out)).not.toThrow();
      expect(out.schemaVersion).toBe(HOOK_DAG_SCHEMA_VERSION);
      expect(out.schemaVersion).toBe(1);
    });
  });

  describe("acyclic DAG — deterministic topological order", () => {
    it("single source, three hooks in order → topological order matches the wiring order", () => {
      const m = makeManifest({
        wirings: [
          { file: ".claude/hooks/c.mjs", event: "PreToolUse", source: "/repo/.claude/settings.json", order: 2 },
          { file: ".claude/hooks/a.mjs", event: "PreToolUse", source: "/repo/.claude/settings.json", order: 0 },
          { file: ".claude/hooks/b.mjs", event: "PreToolUse", source: "/repo/.claude/settings.json", order: 1 },
        ],
      });
      const v = eng.validate({ manifest: m });
      expect(v.ok).toBe(true);
      const ev = v.events.find((e) => e.event === "PreToolUse")!;
      expect(ev.order).toEqual([".claude/hooks/a.mjs", ".claude/hooks/b.mjs", ".claude/hooks/c.mjs"]);
      expect(ev.cycles).toEqual([]);
      expect(ev.edges).toHaveLength(2);
      expect(ev.edges.every((e) => e.reason === "same-source-order")).toBe(true);
    });

    it("two sources, lex-min source first → cross-source edge from lastA → firstB", () => {
      const m = makeManifest({
        wirings: [
          { file: ".claude/hooks/x.mjs", event: "PreToolUse", source: "/home/.claude/settings.json", order: 0 },
          { file: ".claude/hooks/y.mjs", event: "PreToolUse", source: "/home/.claude/settings.json", order: 1 },
          { file: ".claude/hooks/p.mjs", event: "PreToolUse", source: "/repo/.claude/settings.json", order: 0 },
          { file: ".claude/hooks/q.mjs", event: "PreToolUse", source: "/repo/.claude/settings.json", order: 1 },
        ],
      });
      const v = eng.validate({ manifest: m });
      const ev = v.events.find((e) => e.event === "PreToolUse")!;
      // /home sorts before /repo (lex). lastFile(/home) === y, firstFile(/repo) === p.
      const cross = ev.edges.find((e) => e.reason === "cross-source");
      expect(cross?.from).toBe(".claude/hooks/y.mjs");
      expect(cross?.to).toBe(".claude/hooks/p.mjs");
      // Topological order: x, y, p, q (deterministic via Kahn).
      expect(ev.order).toEqual([".claude/hooks/x.mjs", ".claude/hooks/y.mjs", ".claude/hooks/p.mjs", ".claude/hooks/q.mjs"]);
    });

    it("multiple independent events validate separately, results sorted by known-event order", () => {
      const m = makeManifest({
        wirings: [
          { file: ".claude/hooks/a.mjs", event: "Stop", source: "/repo/.claude/settings.json", order: 0 },
          { file: ".claude/hooks/b.mjs", event: "PreToolUse", source: "/repo/.claude/settings.json", order: 0 },
          { file: ".claude/hooks/c.mjs", event: "SessionStart", source: "/repo/.claude/settings.json", order: 0 },
        ],
      });
      const v = eng.validate({ manifest: m });
      expect(v.events.map((e) => e.event)).toEqual(["SessionStart", "Stop", "PreToolUse"]);
      // Each is single-node, no edges, order === [self], no cycles.
      for (const ev of v.events) {
        expect(ev.nodes).toHaveLength(1);
        expect(ev.edges).toHaveLength(0);
        expect(ev.order).toEqual(ev.nodes);
      }
    });
  });

  describe("cycle detection", () => {
    it("two-node cycle: source A has x→y, source B has y→x → cycle of length 2", () => {
      const m = makeManifest({
        wirings: [
          { file: ".claude/hooks/x.mjs", event: "PreToolUse", source: "/a/settings.json", order: 0 },
          { file: ".claude/hooks/y.mjs", event: "PreToolUse", source: "/a/settings.json", order: 1 },
          { file: ".claude/hooks/y.mjs", event: "PreToolUse", source: "/b/settings.json", order: 0 },
          { file: ".claude/hooks/x.mjs", event: "PreToolUse", source: "/b/settings.json", order: 1 },
        ],
      });
      const v = eng.validate({ manifest: m });
      const ev = v.events.find((e) => e.event === "PreToolUse")!;
      expect(ev.order).toBeNull();
      expect(ev.cycles.length).toBeGreaterThanOrEqual(1);
      const cycle = ev.cycles[0];
      // Cycle of length 2 → 3 file entries (start, other, start).
      expect(cycle.files).toHaveLength(3);
      expect(cycle.files[0]).toBe(cycle.files[cycle.files.length - 1]);
      expect(new Set(cycle.files).size).toBe(2);
      expect(v.ok).toBe(false);
      expect(v.summary.cycleCount).toBeGreaterThanOrEqual(1);
      expect(v.summary.dirtyEvents).toBe(1);
    });

    it("three-node cycle: a→b→c→a via three sources → cycle of length 3", () => {
      const m = makeManifest({
        wirings: [
          { file: "a", event: "Stop", source: "/s1.json", order: 0 },
          { file: "b", event: "Stop", source: "/s1.json", order: 1 },
          { file: "b", event: "Stop", source: "/s2.json", order: 0 },
          { file: "c", event: "Stop", source: "/s2.json", order: 1 },
          { file: "c", event: "Stop", source: "/s3.json", order: 0 },
          { file: "a", event: "Stop", source: "/s3.json", order: 1 },
        ],
      });
      const v = eng.validate({ manifest: m });
      const ev = v.events.find((e) => e.event === "Stop")!;
      expect(ev.order).toBeNull();
      expect(ev.cycles).toHaveLength(1);
      expect(new Set(ev.cycles[0].files).size).toBe(3);
      // Length-3 cycle has 4 entries (a,b,c,a) and 3 edges.
      expect(ev.cycles[0].files).toHaveLength(4);
      expect(ev.cycles[0].edges).toHaveLength(3);
    });

    it("cycle in one event does not corrupt a healthy other event", () => {
      const m = makeManifest({
        wirings: [
          { file: ".claude/hooks/clean1.mjs", event: "PreToolUse", source: "/r/settings.json", order: 0 },
          { file: ".claude/hooks/clean2.mjs", event: "PreToolUse", source: "/r/settings.json", order: 1 },
          { file: "a", event: "Stop", source: "/a.json", order: 0 },
          { file: "b", event: "Stop", source: "/a.json", order: 1 },
          { file: "b", event: "Stop", source: "/b.json", order: 0 },
          { file: "a", event: "Stop", source: "/b.json", order: 1 },
        ],
      });
      const v = eng.validate({ manifest: m });
      expect(v.ok).toBe(false);
      expect(v.summary.cleanEvents).toBe(1);
      expect(v.summary.dirtyEvents).toBe(1);
      expect(v.events.find((e) => e.event === "PreToolUse")!.order).not.toBeNull();
      expect(v.events.find((e) => e.event === "Stop")!.order).toBeNull();
    });
  });

  describe("conflicts (non-cycle)", () => {
    it("mixed-block-mode surfaces and lists both sources, ok stays true", () => {
      const m = makeManifest({
        wirings: [
          { file: "h.mjs", event: "PreToolUse", source: "/a.json", order: 0, hardBlock: true },
          { file: "h.mjs", event: "PreToolUse", source: "/b.json", order: 0, hardBlock: false },
        ],
      });
      const v = eng.validate({ manifest: m });
      const ev = v.events.find((e) => e.event === "PreToolUse")!;
      const conflict = ev.conflicts.find((c) => c.kind === "mixed-block-mode");
      expect(conflict?.file).toBe("h.mjs");
      expect(conflict?.sources).toEqual(["/a.json", "/b.json"]);
      expect(conflict?.detail).toMatch(/hard-block/);
      // Conflicts are advisory; the DAG ok flag only flips on cycles.
      expect(v.ok).toBe(true);
      expect(v.summary.conflictCount).toBeGreaterThanOrEqual(1);
    });

    it("duplicate-wiring surfaces when same (event,matcher,source) differs in timeout/args", () => {
      const m = makeManifest({
        wirings: [
          { file: "h.mjs", event: "PreToolUse", source: "/a.json", order: 0, timeoutMs: 1000 },
          { file: "h.mjs", event: "PreToolUse", source: "/a.json", order: 1, timeoutMs: 5000 },
        ],
      });
      const v = eng.validate({ manifest: m });
      const ev = v.events.find((e) => e.event === "PreToolUse")!;
      const conflict = ev.conflicts.find((c) => c.kind === "duplicate-wiring");
      expect(conflict?.file).toBe("h.mjs");
      expect(conflict?.sources).toEqual(["/a.json"]);
      expect(conflict?.detail).toMatch(/ambiguous wiring/);
    });
  });

  describe("determinism", () => {
    it("same input produces byte-identical output (modulo generatedAt)", () => {
      const m = makeManifest({
        wirings: [
          { file: "b", event: "PreToolUse", source: "/r.json", order: 1 },
          { file: "a", event: "PreToolUse", source: "/r.json", order: 0 },
          { file: "c", event: "PreToolUse", source: "/r.json", order: 2 },
        ],
      });
      const v1 = eng.validate({ manifest: m });
      const v2 = eng.validate({ manifest: m });
      const norm = (v: unknown): unknown => JSON.parse(JSON.stringify(v, (k, val) => (k === "generatedAt" ? "X" : val)));
      expect(norm(v1)).toEqual(norm(v2));
    });

    it("events filter restricts results to the named subset", () => {
      const m = makeManifest({
        wirings: [
          { file: "a", event: "PreToolUse", source: "/r.json", order: 0 },
          { file: "b", event: "Stop", source: "/r.json", order: 0 },
        ],
      });
      const v = eng.validate({ manifest: m, events: ["Stop"] });
      expect(v.events.map((e) => e.event)).toEqual(["Stop"]);
      expect(v.summary.totalEvents).toBe(1);
    });
  });

  describe("edge-case inputs", () => {
    it("empty manifest → ok, zero counts everywhere", () => {
      const v = eng.validate({ manifest: makeManifest({ wirings: [] }) });
      expect(v.ok).toBe(true);
      expect(v.summary).toEqual({ totalEvents: 0, totalNodes: 0, totalEdges: 0, cycleCount: 0, conflictCount: 0, cleanEvents: 0, dirtyEvents: 0 });
    });

    it("orphan files (wired:false) are not part of any event DAG", () => {
      const m = makeManifest({
        wirings: [{ file: "wired.mjs", event: "PreToolUse", source: "/r.json", order: 0 }],
        orphanFiles: ["orphan.mjs"],
      });
      const v = eng.validate({ manifest: m });
      const ev = v.events.find((e) => e.event === "PreToolUse")!;
      expect(ev.nodes).toEqual(["wired.mjs"]);
      expect(ev.nodes.includes("orphan.mjs")).toBe(false);
    });

    it("single-node event → topological order is [self], no edges, no cycles", () => {
      const m = makeManifest({ wirings: [{ file: "only.mjs", event: "Notification", source: "/r.json", order: 0 }] });
      const v = eng.validate({ manifest: m });
      const ev = v.events.find((e) => e.event === "Notification")!;
      expect(ev.nodes).toEqual(["only.mjs"]);
      expect(ev.edges).toEqual([]);
      expect(ev.order).toEqual(["only.mjs"]);
      expect(ev.cycles).toEqual([]);
    });

    it("rejects a malformed manifest at the Zod boundary", () => {
      // `manifest.schemaVersion` is z.literal(1); passing 2 must throw.
      const bad: unknown = { ...makeManifest({ wirings: [] }), schemaVersion: 2 };
      expect(() => eng.validate({ manifest: bad as HookManifest })).toThrow();
    });
  });

  describe("real manifest round-trip (smoke)", () => {
    it("HookManifestEngine → HookDAGValidatorEngine succeeds end-to-end on the live repo", () => {
      const me = new HookManifestEngine();
      const manifest = me.generate();
      const v = eng.validate({ manifest });
      // We can't assert ok=true (the real repo may have drift); we assert shape + linkage.
      expect(() => HookDAGValidationSchema.parse(v)).not.toThrow();
      expect(v.manifestGeneratedAt).toBe(manifest.generatedAt);
      expect(v.manifestRepoRoot).toBe(manifest.repoRoot);
      // Every event in the validation must be a key in `manifest.events`.
      for (const e of v.events) {
        expect(Object.keys(manifest.events).includes(e.event)).toBe(true);
      }
      // Summary aggregates must be self-consistent.
      const sumNodes = v.events.reduce((s, e) => s + e.nodes.length, 0);
      const sumEdges = v.events.reduce((s, e) => s + e.edges.length, 0);
      expect(v.summary.totalNodes).toBe(sumNodes);
      expect(v.summary.totalEdges).toBe(sumEdges);
      expect(v.summary.cleanEvents + v.summary.dirtyEvents).toBe(v.events.length);
    });
  });
});
